{
  "verdicts": [
    {
      "candidate_id": "C04",
      "verdict": "true_drift",
      "reason": "The top-level httpx.request signature has no extensions parameter, so the documented call raises TypeError; extensions are accepted by Request and client-level request methods instead.",
      "code_citation": {
        "path": "httpx/_api.py",
        "start_line": 39,
        "end_line": 56,
        "quote": "def request(\n    method: str,\n    url: URL | str,\n    *,\n    params: QueryParamTypes | None = None,\n    content: RequestContent | None = None,\n    data: RequestData | None = None,\n    files: RequestFiles | None = None,\n    json: typing.Any | None = None,\n    headers: HeaderTypes | None = None,\n    cookies: CookieTypes | None = None,\n    auth: AuthTypes | None = None,\n    proxy: ProxyTypes | None = None,\n    timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n    follow_redirects: bool = False,\n    verify: ssl.SSLContext | str | bool = True,\n    trust_env: bool = True,\n) -> Response:"
      },
      "suggested_doc_fix": "Use a client instance when passing extensions, e.g. `with httpx.Client() as client: response = client.request(\"CONNECT\", \"https://www.example.com\", extensions=extensions)`."
    }
  ],
  "additional_findings": [
    {
      "finding_id": "AD-1",
      "drift_kind": "signature",
      "explanation": "The docs call the top-level httpx.get with extensions, but httpx.get does not accept an extensions parameter.",
      "doc_citation": {
        "path": "docs/advanced/extensions.md",
        "start_line": 169,
        "end_line": 169,
        "quote": "response = httpx.get(\"https://www.example.com\", extensions=extensions)"
      },
      "code_citation": {
        "path": "httpx/_api.py",
        "start_line": 174,
        "end_line": 186,
        "quote": "def get(\n    url: URL | str,\n    *,\n    params: QueryParamTypes | None = None,\n    headers: HeaderTypes | None = None,\n    cookies: CookieTypes | None = None,\n    auth: AuthTypes | None = None,\n    proxy: ProxyTypes | None = None,\n    follow_redirects: bool = False,\n    verify: ssl.SSLContext | str | bool = True,\n    timeout: TimeoutTypes = DEFAULT_TIMEOUT_CONFIG,\n    trust_env: bool = True,\n) -> Response:"
      },
      "proposed_fix": "Change the example to use a client instance, e.g. `with httpx.Client() as client: response = client.get(\"https://www.example.com\", extensions=extensions)`."
    },
    {
      "finding_id": "AD-2",
      "drift_kind": "signature",
      "explanation": "The docs use httpx.Mounts as a transport passed to transport=, but the supported configuration is the mounts parameter, a mapping of URL patterns to transports.",
      "doc_citation": {
        "path": "docs/advanced/transports.md",
        "start_line": 190,
        "end_line": 194,
        "quote": "transport = httpx.Mounts({\n    'http://': HTTPSRedirect()\n    'https://': httpx.HTTPTransport()\n})\nclient = httpx.Client(transport=transport)"
      },
      "code_citation": {
        "path": "httpx/_client.py",
        "start_line": 652,
        "end_line": 652,
        "quote": "        mounts: None | (typing.Mapping[str, BaseTransport | None]) = None,"
      },
      "proposed_fix": "Use the mounts parameter directly, e.g. `client = httpx.Client(mounts={'http://': HTTPSRedirect(), 'https://': httpx.HTTPTransport()})`."
    },
    {
      "finding_id": "AD-3",
      "drift_kind": "other",
      "explanation": "The docs refer to response.iter_content(), but Response provides iter_bytes() instead.",
      "doc_citation": {
        "path": "docs/advanced/clients.md",
        "start_line": 183,
        "end_line": 183,
        "quote": "This interface is required for properly determining download progress, because the total number of bytes returned by `response.content` or `response.iter_content()` will not always correspond with the raw content length of the response if HTTP response compression is being used."
      },
      "code_citation": {
        "path": "httpx/_models.py",
        "start_line": 884,
        "end_line": 884,
        "quote": "    def iter_bytes(self, chunk_size: int | None = None) -> typing.Iterator[bytes]:"
      },
      "proposed_fix": "Replace `response.iter_content()` with `response.iter_bytes()` in the sentence."
    }
  ]
}
